"""One observation-driven route through a maze, drawer, key, and locked door.

The maze and fixture simulators retain their own body dynamics. This module
composes their public skills and keeps fixture actions local to the visited site.
Simulator positions and fixture names are used only to build and score a scene.
"""

from __future__ import annotations

from dataclasses import dataclass, field

from pai.cognition.discovery import run_discovery_cognitive
from pai.discovery.interface import Outcome
from pai.maze.agent import Explorer
from pai.maze.env import Cell, MazeWorld, Observation, neighbors


def _distance(a: Cell, b: Cell) -> int:
    return abs(a[0] - b[0]) + abs(a[1] - b[1])


class KeyChainMaze:
    """Expose a drawer and a locked passage as observed maze landmarks."""

    def __init__(self, maze: MazeWorld, drawer: Cell):
        if drawer == maze.goal or drawer == maze.start or maze.grid[drawer]:
            raise ValueError("drawer must occupy a separate traversable cell")
        self.maze = maze
        self.drawer = drawer
        self.door = maze.goal
        self.door_open = False

    def observe(self, collided: bool = False) -> Observation:
        base = self.maze.observe(collided)
        visible = dict(base.visible)
        if self.drawer in visible:
            visible[self.drawer] = "drawer"
        if self.door in visible:
            visible[self.door] = "exit" if self.door_open else "door"
        return Observation(base.position, visible, collided,
                           self.door_open and base.position == self.door)

    def step(self, move: Cell) -> Observation:
        target = self.maze.position[0] + move[0], self.maze.position[1] + move[1]
        if target == self.door and not self.door_open:
            self.maze.steps += 1
            self.maze.events.append({"step": self.maze.steps, "type": "locked_passage_contact",
                                     "position": target})
            return self.observe(True)
        return self._after(self.maze.step(move))

    def _after(self, base: Observation) -> Observation:
        return self.observe(base.collided)


class LocalFixture:
    """A fixture's public entities and actions, restricted by the body's location."""

    def __init__(self, world, part_ids: set[str], goal_feature: str,
                 object_ids: set[str] | None = None):
        self.world = world
        self.part_ids = set(part_ids)
        self.object_ids = object_ids
        self.goal_feature = goal_feature

    def _ids(self) -> set[str]:
        if self.object_ids is not None:
            return self.part_ids | self.object_ids
        return self.part_ids | {e.id for e in self.world.entities() if e.kind == "object"}

    def entities(self):
        ids = self._ids()
        return [e for e in self.world.entities() if e.id in ids]

    def features(self):
        ids = self._ids()
        return {key: value for key, value in self.world.features().items()
                if key == "body:hand" or (key.startswith(("part:", "obj:"))
                                          and key.split(":", 1)[1].split(".", 1)[0] in ids)}

    def actions(self):
        ids = self._ids()
        return [action for action in self.world.actions()
                if action[1] in ids and (action[0] != "insert" or action[2] in self.part_ids)]

    def execute(self, action):
        if action not in self.actions():
            raise ValueError(f"fixture action out of reach: {action}")
        result = self.world.execute(action)
        ids = self._ids()
        changed = {key: value for key, value in result.changed.items()
                   if key == "body:hand" or (key.startswith(("part:", "obj:"))
                                             and key.split(":", 1)[1].split(".", 1)[0] in ids)}
        return Outcome(action, result.executed, result.stalled, changed,
                       [e for e in result.revealed if e.id in ids], result.cost, result.notes)

    def goal(self):
        return {self.goal_feature: "open"}

    def goal_reached(self):
        return self.features().get(self.goal_feature) == "open"


@dataclass
class KeyChainResult:
    success: bool
    stage: str
    moves: int
    fixture_actions: int
    drawer_open: bool
    door_open: bool
    entered_exit: bool
    events: list[dict] = field(default_factory=list)


class KeyChainAgent:
    """Maintain one place map while switching between spatial and fixture goals."""

    def __init__(self, size: int, sensor_range: int, seed: int = 0):
        self.explorer = Explorer(sensor_range, size, seed)
        self.sightings: dict[str, Cell] = {}

    def move(self, obs: Observation, target: str) -> Cell | None:
        for cell, kind in obs.visible.items():
            if kind in ("drawer", "door", "exit"):
                self.sightings["door" if kind == "exit" else kind] = cell
        known = self.sightings.get(target)
        visible = {cell: ("goal" if kind == target else
                          "wall" if kind == "door" and target == "drawer" else
                          "floor" if kind in ("drawer", "door", "exit") else kind)
                   for cell, kind in obs.visible.items()}
        # The same map survives the switch from drawer to door. Re-label older
        # sightings so a previously visited destination remains routable.
        for name, cell in self.sightings.items():
            if cell in self.explorer.memory.cells:
                self.explorer.memory.cells[cell] = (
                    "goal" if name == target else
                    "wall" if name == "door" and target == "drawer" else "floor")
        if target == "door" and known is not None:
            self.explorer.memory.cells[known] = "goal"
            self.explorer.memory.edges.setdefault(known, set())
            for near in neighbors(known):
                if self.explorer.memory.cells.get(near) in ("floor", "goal"):
                    self.explorer.memory.edges[known].add(near)
                    self.explorer.memory.edges.setdefault(near, set()).add(known)
        planned = self.explorer.act(Observation(obs.position, visible, obs.collided, False))
        if known is not None and known != obs.position:
            route = self.explorer.memory.route(obs.position, known)
            if route:
                return route[0][0] - obs.position[0], route[0][1] - obs.position[1]
        return planned


def _drawer_cell(maze: MazeWorld) -> Cell:
    """Scene generation only: place the drawer away from the start and door."""
    distances = {maze.start: 0}
    queue = [maze.start]
    for cell in queue:
        for near in neighbors(cell):
            if (near != maze.goal and 0 <= near[0] < maze.size and
                    0 <= near[1] < maze.size and not maze.grid[near] and
                    near not in distances):
                distances[near] = distances[cell] + 1
                queue.append(near)
    candidates = [cell for cell in distances if cell != maze.goal and
                  _distance(cell, maze.goal) >= 4]
    return max(candidates, key=lambda cell: (distances[cell], cell))


def _repair_opening(door: LocalFixture, object_id: str, limit: int = 24) -> tuple[int, list[dict]]:
    """Retry a carried object's effect and nearby fixture probes from observations.

    This is a bounded fallback after the discovery policy has spent its budget.
    It uses appearance, angle and action outcomes, never fixture role names.
    """
    count, events = 0, []

    def act(action):
        nonlocal count
        if count >= limit or action not in door.actions():
            return None
        outcome = door.execute(action)
        count += 1
        events.append({"stage": "repair", "action": list(action),
                       "stalled": outcome.stalled, "changed": bool(outcome.changed),
                       "notes": outcome.notes})
        return outcome

    where = door.features().get(f"obj:{object_id}.where", "")
    if where == "free" and door.features().get("body:hand") == "empty":
        act(("pick", object_id))
    if door.features().get("body:hand") == object_id:
        where = door.features().get(f"obj:{object_id}.where", "")
        if where == "held":
            entities = {e.id: e for e in door.entities()}
            inserts = [a for a in door.actions() if a[0] == "insert" and a[1] == object_id]
            inserts.sort(key=lambda a: (float(entities[a[2]].attrs.get("size", 1.0)), a[2]))
            for action in inserts:
                outcome = act(action)
                if outcome is not None and not outcome.stalled and door.features().get(
                        f"obj:{object_id}.where", "").startswith("in:"):
                    break
    if door.features().get(f"obj:{object_id}.where", "").startswith("in:"):
        for sign in (1, -1):
            outcome = act(("turn_held", object_id, sign))
            if outcome is not None and not outcome.stalled:
                break
    if door.features().get("body:hand") == object_id:
        act(("release", object_id))

    entities = {e.id: e for e in door.entities()}
    for entity in entities.values():
        if entity.kind != "part" or entity.attrs.get("shape") != "wing":
            continue
        angle = door.features().get(f"part:{entity.id}.angle")
        if angle in ("pos", "neg"):
            act(("turn", entity.id, -1 if angle == "pos" else 1))
    goal_id = door.goal_feature.split(":", 1)[1].split(".", 1)[0]
    goal = entities.get(goal_id)
    probes = [a for a in door.actions() if a[0] in ("turn_pull", "turn_push", "press_push", "pull", "push")
              and a[1] in entities and entities[a[1]].graspable]
    probes.sort(key=lambda a: (
        0 if entities[a[1]].attrs.get("shape") in ("bar", "round", "ball") else 1,
        sum((x-y)**2 for x, y in zip(entities[a[1]].pos, goal.pos)) if goal else 0,
        {"turn_pull": 0, "turn_push": 1, "press_push": 2, "pull": 3, "push": 4}[a[0]], a))
    for action in probes:
        if door.goal_reached() or count >= limit:
            break
        act(action)
    return count, events


def run_key_chain(maze: MazeWorld, fixture, *, seed: int = 0,
                  move_budget: int = 700, fixture_budget: int = 120,
                  recipes=None, learn_recipe: bool = False) -> KeyChainResult:
    """Find the drawer, carry an observed object, unlock the door, enter the exit.

    Fixture identity is used by this environment adapter to scope reachability.
    The navigation and discovery policies see only observations/actions/outcomes.
    """
    scene = KeyChainMaze(maze, _drawer_cell(maze))
    agent = KeyChainAgent(maze.size, maze.sensor_range, seed)
    ids = fixture.pid
    drawer_id, door_id = ids["drawer"], ids["door"]
    drawer = LocalFixture(fixture, {drawer_id}, f"part:{drawer_id}.open", set())
    door_parts = {ids[name] for name in ("door", "handle", "thumb", "cylinder") if name in ids}
    door = LocalFixture(fixture, door_parts, f"part:{door_id}.open", set())
    events: list[dict] = []
    fixture_actions = 0
    pending_keys: list[str] = []
    stage = "find_drawer"
    obs = scene.observe()
    while maze.steps < move_budget:
        if stage in ("find_drawer", "return_drawer") and obs.visible.get(obs.position) == "drawer":
            if stage == "find_drawer":
                before_objects = {e.id for e in fixture.entities() if e.kind == "object"}
                record, _ = run_discovery_cognitive(drawer, seed=seed, budget_actions=fixture_budget)
                fixture_actions += record.steps
                events.append({"stage": "open_drawer", "success": record.success,
                               "actions": record.steps})
                if not record.success:
                    stage = "open_drawer_failed"
                    break
                # The pool contains only newly revealed elongated objects.
                # Their simulator match labels are never passed to this policy.
                pending_keys = sorted(e.id for e in fixture.entities() if e.kind == "object"
                                      and e.id not in before_objects and
                                      e.attrs.get("shape") == "elongated")
            if not pending_keys:
                stage = "keys_exhausted"
                break
            key_id = pending_keys.pop(0)
            drawer.object_ids = {key_id}
            outcome = drawer.execute(("pick", key_id))
            fixture_actions += 1
            events.append({"stage": "carry_object", "object": key_id,
                           "executed": outcome.executed, "stalled": outcome.stalled})
            if fixture.features().get("body:hand") != key_id:
                stage = "pick_failed"
                break
            stage = "find_door"
            door.object_ids = {key_id}
        if stage == "find_door" and "door" in agent.sightings:
            door_cell = agent.sightings["door"]
            if _distance(obs.position, door_cell) == 1:
                stage = "open_door"
                held = fixture.features().get("body:hand", "empty")
                if held != "empty":
                    inserts = [action for action in door.actions()
                               if action[0] == "insert" and action[1] == held]
                    appearances = {entity.id: entity for entity in door.entities()}
                    inserts.sort(key=lambda action: (
                        float(appearances[action[2]].attrs.get("size", 1.0)), action[2]))
                    inserted = False
                    for action in inserts:
                        outcome = door.execute(action)
                        fixture_actions += 1
                        events.append({"stage": "try_fixture", "action": list(action),
                                       "stalled": outcome.stalled})
                        if not outcome.stalled and fixture.features().get(
                                f"obj:{held}.where", "").startswith("in:"):
                            inserted = True
                            break
                    if not inserted:
                        events.append({"stage": "diagnose", "cause": "incompatible_object_or_alignment",
                                       "object": held, "evidence": "all local insertions stalled"})
                        door.execute(("release", held))
                        fixture_actions += 1
                        stage = "return_drawer"
                        continue
                    rotated = False
                    for sign in (1, -1):
                        action = ("turn_held", held, sign)
                        outcome = door.execute(action)
                        fixture_actions += 1
                        events.append({"stage": "try_turn", "action": list(action),
                                       "stalled": outcome.stalled})
                        if not outcome.stalled:
                            rotated = True
                            break
                    door.execute(("release", held))
                    fixture_actions += 1
                    if not rotated:
                        # A seated object that cannot rotate in either direction
                        # is disconfirmed by contact, independent of key identity.
                        events.append({"stage": "diagnose", "cause": "incompatible_key",
                                       "object": held, "evidence": "both inserted turns stalled"})
                        withdraw = door.execute(("pick", held))
                        fixture_actions += 1
                        if withdraw.stalled or fixture.features().get("body:hand") != held:
                            stage = "withdraw_failed"
                            break
                        door.execute(("release", held))
                        fixture_actions += 1
                        stage = "return_drawer"
                        continue
                record, log = run_discovery_cognitive(door, seed=seed,
                                                      budget_actions=fixture_budget,
                                                      object_trials=True, recipes=recipes)
                fixture_actions += record.steps
                events.append({"stage": stage, "success": record.success,
                               "actions": record.steps})
                if not record.success:
                    repair_count, repair_events = _repair_opening(door, held)
                    fixture_actions += repair_count
                    events.extend(repair_events)
                    if not door.goal_reached():
                        events.append({"stage": "diagnose", "cause": "opening_still_blocked",
                                       "evidence": "key and local release probes exhausted"})
                        break
                if learn_recipe and recipes is not None:
                    recipes.learn(log, source=f"key_chain_seed_{seed}")
                scene.door_open = True
                stage = "pass_door"
        if stage == "pass_door":
            door_cell = agent.sightings["door"]
            move = (door_cell[0] - obs.position[0], door_cell[1] - obs.position[1])
            obs = scene.step(move)
            stage = "complete" if obs.reached_goal else "pass_failed"
            break
        target = "drawer" if stage in ("find_drawer", "return_drawer") else "door"
        move = agent.move(obs, target)
        if move is None:
            stage = "route_exhausted"
            break
        obs = scene.step(move)
    if maze.steps >= move_budget and stage not in ("complete", "pass_failed"):
        stage = "move_budget"
    return KeyChainResult(stage == "complete", stage, maze.steps, fixture_actions,
                          drawer.goal_reached(), door.goal_reached(), obs.reached_goal, events)

scripts/key_chain_v2_eval.py.text:
"""CPU-only development, frozen recipe, paired final gate and event-log scoring.

The simulator answer key lives in ScoredMock only. Agents get EvidenceWorld.
Outputs are append-only: refusing an existing path prevents silent gate reruns.
"""
from __future__ import annotations

import argparse
from dataclasses import asdict
import hashlib
import json
import math
from pathlib import Path
import sys
import time
from concurrent.futures import ThreadPoolExecutor
from types import SimpleNamespace
import numpy as np

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from pai.discovery.agent import _Episode
from pai.discovery.interface import PROBE_KINDS
from pai.discovery.key_chain_recipe import (ChainMemory, EvidenceWorld, FAILURE_CAUSES,
    FailureLikelihood, LearnedChain, RecipeDiscoveryAgent, failure_tokens)
from pai.discovery.mock import MockWorld, Scenario
from pai.discovery.recipes import Recipe


class ScoredMock(MockWorld):
    """Original mock mechanics plus truth-only failed-opening event records.

    A random, permanently obstructed door is an explicit additional mock case.
    It cannot open. No key is forced wrong, no rollout action is forced, and
    role IDs/labels are never included in the policy's outcome or features.
    """
    def __init__(self, scenario, obstructed=False):
        super().__init__(scenario)
        self.obstructed = obstructed
        self.failures = []
        self.current_action = None

    def execute(self, action):
        self.current_action = tuple(action)
        out = super().execute(action)
        if (out.executed and out.stalled and action[0] == "turn_held"
                and self.objs[action[1]]["where"].startswith("in:")
                and not self.objs[action[1]]["matches"]):
            self.failures.append({"step": self.n - 1, "cause": "wrong_key", "action": list(action)})
        return out

    def _move(self, name, fam, released):
        on_leaf = name in ("door", "handle", "thumb", "door_dial", "door_hook", "door_wing")
        opening_attempt = on_leaf and not self.door_open
        # Wrong-direction / ungraspable panel pulls are physical blocking in
        # this discrete mock. A lock has priority over latch when both hold.
        cause = None
        if opening_attempt:
            if fam != self.swing or (name == "door" and fam == "pull"):
                cause = "blocked"
            elif self.thumb == 1 or self.tail == 1:
                matching_rest = any(o["matches"] and o["where"] == f"in:{self.pid.get('cylinder')}"
                                    and o["angle"] == 0 for o in self.objs.values())
                cause = "key_not_turned" if self.tail == 1 and matching_rest and self.thumb == 0 else "locked"
            elif self.latch and not released:
                cause = "latched"
            elif self.obstructed:
                cause = "blocked"
        if opening_attempt and self.obstructed and cause == "blocked" and fam == self.swing:
            stalled = True
        else:
            stalled = super()._move(name, fam, released)
        if opening_attempt and stalled:
            self.failures.append({"step": self.n - 1, "cause": cause or "blocked",
                                  "action": list(self.current_action)})
        return stalled


def wilson(k, n):
    if not n:
        return [None, None]
    z = 1.959963984540054
    p, z2 = k / n, z * z
    mid = (p + z2 / (2 * n)) / (1 + z2 / n)
    half = z * math.sqrt(p * (1 - p) / n + z2 / (4 * n * n)) / (1 + z2 / n)
    return [max(0, mid - half), min(1, mid + half)]


def source_hashes():
    names = ['pai/discovery/key_chain_recipe.py', 'pai/discovery/agent.py',
             'pai/discovery/belief.py', 'pai/discovery/recipes.py', 'pai/discovery/mock.py',
             'pai/maze/key_chain.py', 'scripts/key_chain_v2_eval.py']
    return {n: hashlib.sha256((ROOT / n).read_bytes()).hexdigest() for n in names}


def scan_seeds():
    """Conservative metadata inventory, including nested discovery result dirs."""
    files = []
    for p in (ROOT / 'results').glob('*'):
        if p.name.startswith(('key_chain_', 'discovery_')) and not p.name.startswith('key_chain_v2_'):
            files.extend(p.rglob('*.json') if p.is_dir() else [p] if p.suffix == '.json' else [])
    found = {}
    def walk(x, key=''):
        if isinstance(x, dict):
            for k, v in x.items():
                walk(v, k)
        elif isinstance(x, list):
            for v in x:
                walk(v, key)
        elif isinstance(x, int) and not isinstance(x, bool) and 'seed' in key.lower():
            seeds.add(x)
    for p in files:
        seeds = set()
        try:
            walk(json.loads(p.read_text(encoding='utf-8')))
            found[str(p.relative_to(ROOT))] = sorted(seeds)
        except (ValueError, OSError):
            found[str(p.relative_to(ROOT))] = 'unreadable'
    return found


def scene(seed, type_name, case):
    state = {'unlocked': 'unlocked', 'latched': 'latch', 'locked': 'deadbolt',
             'key': 'key', 'both': 'both', 'blocked': 'latch'}[case]
    return ScoredMock(Scenario(type_name, state, 'drawer', n_keys=2, seed=seed,
                               p_fail=0.03, pen=True, shared_shapes=True, door_hook=True),
                      obstructed=case == 'blocked')


def run_learned(seed, type_name, case, budget, memory=None, learn=False):
    world = scene(seed, type_name, case)
    agent = RecipeDiscoveryAgent(seed=seed, memory=memory)
    log = agent.run(world, budget)
    if learn and log.reached_goal:
        memory.learn(log, f'development seed {seed}')
    record = record_log(world, log, seed, type_name, case)
    record.update(recipe_actions=agent.replay_actions, repair_reason=agent.repair_reason)
    return record, log


def record_log(world, log, seed, type_name, case):
    record = {'seed': seed, 'type': type_name, 'case': case, 'success': log.reached_goal,
              'actions': log.n_actions, 'actions_to_success': log.n_actions if log.reached_goal else None,
              'time_cost': log.time_cost, 'stop': log.stopped_reason,
              'goal': log.goal, 'belief': log.final_map, 'trace': [
                  {'action': list(a), 'before': st, 'outcome': asdict(o), 'mode': mode}
                  for a, st, o, mode in zip(log.actions, log.states, log.outcomes, log.modes)],
              'events': world.events, 'failure_events': world.failures}
    return record


def serialize_memory(m):
    return {'chains': [r.to_dict() for r in m.chains],
            'priors': [asdict(r) for r in m.priors.recipes]}


def restore_memory(d, sequence=True):
    m = ChainMemory()
    if sequence:
        m.chains = [LearnedChain.from_dict(r) for r in d['chains']]
    for r in d['priors']:
        m.priors.add(Recipe(**r))
    return m


def explain_record(record, log, model):
    # Predictions computed for EVERY executed, stalled probe/inserted turn.
    # The truth-only log is joined afterwards to define the scoring denominator;
    # it is never consulted to select the evidence or generate a prediction.
    predictions = {}
    for i, (a, o) in enumerate(zip(log.actions, log.outcomes)):
        if o.executed and o.stalled and a[0] in (*PROBE_KINDS, 'turn_held'):
            predictions[i] = model.predict(failure_tokens(log, i))
    record['explanations'] = [{'step': i, **p} for i, p in predictions.items()]
    record['scored_explanations'] = [{**event, **predictions[event['step']],
                                     'truth': event['cause'],
                                     'correct': predictions[event['step']]['cause'] == event['cause']}
                                    for event in record['failure_events']
                                    if event['step'] in predictions]


def summarize(rows):
    n = len(rows)
    success = sum(r['success'] for r in rows)
    acts = [r['actions_to_success'] for r in rows if r['success']]
    exp = [e for r in rows for e in r.get('scored_explanations', [])]
    solvable = [r for r in rows if r['case'] != 'blocked']
    solved = sum(r['success'] for r in solvable)
    return {'n': n, 'passed': success, 'success_rate': success / n,
            'wilson95': wilson(success, n),
            'solvable': {'n': len(solvable), 'passed': solved,
                         'wilson95': wilson(solved, len(solvable))},
            'mean_actions_all': sum(r['actions'] for r in rows) / n,
            'mean_actions_to_success': sum(acts) / len(acts) if acts else None,
            'explanations': {'n': len(exp), 'correct': sum(e['correct'] for e in exp),
                'abstained': sum(e['cause'] == 'unknown' for e in exp),
                'by_cause': {c: {'n': sum(e['truth'] == c for e in exp),
                                 'correct': sum(e['truth'] == c and e['correct'] for e in exp),
                                 'abstained': sum(e['truth'] == c and e['cause'] == 'unknown' for e in exp)}
                             for c in FAILURE_CAUSES}}}


def development(args):
    memory = ChainMemory()
    rows, examples = [], []
    # Training/diagnosis development episodes, never used for final estimates.
    with ThreadPoolExecutor(max_workers=args.workers) as pool:
        jobs = []
        for i in range(args.layouts):
            for j, case in enumerate(('unlocked', 'latched', 'locked', 'key', 'both', 'blocked')):
                seed = args.seed + i * 6 + j
                jobs.append(pool.submit(run_learned, seed, 'hd_lever_pull_right', case, args.budget))
        for job in jobs:
            record, log = job.result()
            seed, case = record['seed'], record['case']
            if case == 'both' and log.reached_goal and not memory.chains:
                memory.learn(log, f'development seed {seed}')
            for e in record['failure_events']:
                examples.append((failure_tokens(log, e['step']), e['cause']))
            rows.append(record)
            print(f'dev {seed} {case}: {log.reached_goal} / {log.n_actions}', flush=True)
    if not memory.chains:
        raise RuntimeError('No successful both-lock episode: no chain learned')
    model = FailureLikelihood().fit(examples)
    return {'kind': 'development', 'seed_inventory': scan_seeds(), 'sources': source_hashes(),
            'config': vars_json(args), 'memory': serialize_memory(memory),
            'failure_model': model.to_dict(), 'teaching_examples': len(examples), 'episodes': rows}


def teacher(args):
    """Uniform motor experiments, with no role scoping or forced wrong object.

    Additional development evidence is needed because the discovery policy
    almost always turns a newly inserted object before probing the door.
    """
    rows = []
    for i in range(args.layouts):
        seed = args.seed + i
        case = ('key', 'both', 'latched', 'locked', 'unlocked', 'blocked')[i % 6]
        world = scene(seed, 'hd_lever_pull_right', case)
        body = EvidenceWorld(world)
        ep = _Episode(body)
        rng = np.random.default_rng(seed)
        for _ in range(args.budget):
            acts = body.actions()
            ep.step(acts[int(rng.integers(len(acts)))], 'uniform_experiment')
            if body.goal_reached():
                break
        log = ep.finish('goal' if body.goal_reached() else 'budget')
        rows.append(record_log(world, log, seed, 'hd_lever_pull_right', case))
    return {'kind': 'random_development_teacher', 'sources': source_hashes(),
            'config': vars_json(args), 'episodes': rows}


def freeze(args):
    development_data = json.loads(args.model.read_text(encoding='utf-8'))
    teacher_data = json.loads(args.teacher.read_text(encoding='utf-8'))
    examples = []
    for r in development_data['episodes'] + teacher_data['episodes']:
        trace = r['trace']
        goal = r.get('goal') or scene(r['seed'], r['type'], r['case']).goal()
        log = SimpleNamespace(goal=goal, actions=[tuple(t['action']) for t in trace],
                              states=[t['before'] for t in trace],
                              outcomes=[SimpleNamespace(**t['outcome']) for t in trace])
        for e in r['failure_events']:
            examples.append((failure_tokens(log, e['step']), e['cause']))
    model = FailureLikelihood().fit(examples)
    return {'kind': 'frozen_development_model', 'sources': source_hashes(),
            'config': vars_json(args), 'memory': development_data['memory'],
            'failure_model': model.to_dict(), 'teaching_examples': len(examples),
            'development_seeds': [r['seed'] for r in development_data['episodes'] + teacher_data['episodes']],
            'input_sha256': {str(p): hashlib.sha256(p.read_bytes()).hexdigest()
                             for p in (args.model, args.teacher)},
            'seed_inventory': scan_seeds(),
            'episodes': development_data['episodes']}


def run_scripted(seed, type_name, case, budget):
    from pai.maze.env import MazeWorld
    from pai.maze.key_chain import run_key_chain
    world = scene(seed, type_name, case)
    result = run_key_chain(MazeWorld(seed=seed, size=15), world, seed=seed,
                           move_budget=900, fixture_budget=budget)
    # Its per-fixture budget can exceed the new agent's total. Retain actual
    # actions and make this asymmetry explicit rather than hide it.
    return {'seed': seed, 'type': type_name, 'case': case, 'success': result.success,
            'actions': result.fixture_actions,
            'actions_to_success': result.fixture_actions if result.success else None,
            'moves': result.moves, 'stop': result.stage, 'events': world.events,
            'failure_events': world.failures, 'script_reports': result.events}


def evaluate(args):
    frozen = json.loads(args.model.read_text(encoding='utf-8'))
    if frozen['sources'] != source_hashes():
        raise RuntimeError('Sources changed since freezing; create a new development model first')
    dev_seeds = set(frozen.get('development_seeds', [r['seed'] for r in frozen['episodes']]))
    proposed = set(range(args.seed, args.seed + args.layouts * 6))
    used = {s for v in frozen['seed_inventory'].values() if isinstance(v, list) for s in v}
    if proposed & (used | dev_seeds):
        raise ValueError('Evaluation seed overlap')
    model = FailureLikelihood.from_dict(frozen['failure_model'])
    rows = []
    with ThreadPoolExecutor(max_workers=args.workers) as pool:
        jobs = []
        for i in range(args.layouts):
            for j, case in enumerate(('unlocked', 'latched', 'locked', 'key', 'both', 'blocked')):
                seed = args.seed + i * 6 + j
                type_name = 'hd_lever_pull_right' if i < args.layouts // 2 else 'hd_knob_pull_right'
                jobs.append(pool.submit(evaluate_pair, seed, type_name, case, args.budget,
                                        frozen['memory'], model.to_dict()))
        for job in jobs:
            row = job.result()
            rows.append(row)
            seed, case, paired = row['seed'], row['case'], row['modes']
            print(f"gate {seed} {case}: " + ', '.join(f"{m} {r['success']}/{r['actions']}"
                                                       for m, r in paired.items()), flush=True)
    return {'kind': args.command, 'sources': source_hashes(), 'config': vars_json(args),
            'model_sha256': hashlib.sha256(args.model.read_bytes()).hexdigest(),
            'summary': {group: {mode: summarize([r['modes'][mode] for r in rows
                                               if group == 'all' or r['type'] == group])
                                for mode in rows[0]['modes']}
                        for group in ('all', 'hd_lever_pull_right', 'hd_knob_pull_right')},
            'episodes': rows}


def evaluate_pair(seed, type_name, case, budget, frozen_memory, failure_model):
    model = FailureLikelihood.from_dict(failure_model)
    paired = {}
    for mode in ('cold', 'warm', 'prior_only', 'no_recipe'):
        if mode == 'no_recipe':
            paired[mode] = copy_record(paired['cold'])
            continue
        memory = None if mode == 'cold' else restore_memory(frozen_memory, mode == 'warm')
        rec, log = run_learned(seed, type_name, case, budget, memory)
        explain_record(rec, log, model)
        paired[mode] = rec
    paired['scripted'] = run_scripted(seed, type_name, case, budget)
    return {'seed': seed, 'type': type_name, 'case': case, 'modes': paired}


def copy_record(record):
    return json.loads(json.dumps(record))


def vars_json(args):
    return {k: str(v) if isinstance(v, Path) else v for k, v in vars(args).items()}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('command', choices=('develop', 'teacher', 'freeze', 'validate', 'final'))
    parser.add_argument('--seed', type=int, required=True)
    parser.add_argument('--layouts', type=int, default=4)
    parser.add_argument('--budget', type=int, default=800)
    parser.add_argument('--workers', type=int, choices=(1, 2), default=2)
    parser.add_argument('--model', type=Path)
    parser.add_argument('--teacher', type=Path)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    if args.output.exists():
        raise FileExistsError(args.output)
    if args.command in ('validate', 'final', 'freeze') and not args.model:
        parser.error('--model required')
    started = time.time()
    report = {'develop': development, 'teacher': teacher, 'freeze': freeze,
              'validate': evaluate, 'final': evaluate}[args.command](args)
    report['wall_seconds'] = time.time() - started
    args.output.write_text(json.dumps(report, indent=2) + '\n', encoding='utf-8')
    print(json.dumps(report.get('summary', {'teaching_examples': report.get('teaching_examples')})), flush=True)


if __name__ == '__main__':
    main()

